// Verus program: element-wise bitwise AND of two u8 vectors
#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires
        a.len() == b.len(),
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == (a[i] & b[i]),
{
    let mut result: Vec<u8> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            a.len() == b.len(),
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == (a[j] & b[j]),
        decreases
            a.len() - i,
    {
        // i < a.len() implies i < b.len() from a.len() == b.len()
        result.push(a[i] & b[i]);
        i += 1;
    }

    result
}

} // verus!